#!/usr/bin/env node
// build-bundle.js — creates data-bundle.js with all runtime data inlined
// so the app works on file:// protocol without fetch/XHR

const fs = require("fs");
const path = require("path");

function loadJson(file) {
  return JSON.parse(fs.readFileSync(path.join(__dirname, file), "utf8"));
}

// Load all data files
const products = loadJson("data/products.json");
const recipes = loadJson("data/recipes.json");
const budget = loadJson("data/budget-tiers.json");
const profiles = loadJson("data/family-profiles.json");
const storePrices = loadJson("data/store-prices.json");
const defaultPlan = loadJson("data/plans.json");
const defaultRules = loadJson("data/inventory-rules.json");

// Load all profile-specific plans
const planManifest = loadJson("data/plans/manifest.json");
const profilePlans = {};
for (const p of planManifest.profiles || []) {
  const pid = p.id;
  if (!pid) continue;
  try {
    profilePlans[`plan_${pid}`] = loadJson(`data/plans/plan_${pid}.json`);
    profilePlans[`inv_${pid}`] = loadJson(`data/plans/inv_${pid}.json`);
  } catch (_) {}
}

// Strip fat from recipes (7.7MB → ~1.3MB)
const cleanRecipes = {};
for (const [k, v] of Object.entries(recipes.recipes || {})) {
  cleanRecipes[k] = {
    title: v.title, type: v.type, time: v.time, store: v.store,
    ingredients: v.ingredients, steps: v.steps, usage: v.usage,
    activeMinutes: v.activeMinutes, containerRule: v.containerRule,
    cost: v.cost, costLabel: v.costLabel, macros: v.macros,
    kcal: v.kcal, quality: v.quality,
  };
  if (v.box) cleanRecipes[k].box = v.box;
}

// Build INVENTORY_ITEMS
const INVENTORY_ITEMS = {};
for (const [id, p] of Object.entries(products.products || {})) {
  INVENTORY_ITEMS[id] = [p.name, p.unit, p.storage];
}

const bundle = {
  products: products.products,
  recipes: cleanRecipes,
  budget,
  profiles,
  storePrices,
  defaultPlan,
  defaultRules,
  profilePlans,
  INVENTORY_ITEMS,
  storeSections: products.storeSections || [],
  mealOrder: ["Завтрак","Обед","Полдник","Ужин","Чай"],
};

const json = JSON.stringify(bundle);
const js = `// FoodFlow data bundle — auto-generated by build-bundle.js\n// This file allows the app to work on file:// protocol\nwindow.FoodFlowBundle=${json};\n`;

fs.writeFileSync(path.join(__dirname, "data-bundle.js"), js);
console.log(`data-bundle.js: ${(js.length / 1024 / 1024).toFixed(1)}MB`);
